type Jar = Map<string, string>;
function applySetCookies(jar: Jar, res: Response) {
  for (const sc of res.headers.getSetCookie?.() ?? []) {
    const [pair] = sc.split(";");
    const eq = pair.indexOf("=");
    if (eq < 0) continue;
    const name = pair.slice(0, eq).trim();
    let value = pair.slice(eq + 1).trim();
    if (/^(deleted|undefined)$/i.test(value)) value = "";
    if (value === "") jar.delete(name); else jar.set(name, value);
  }
}
function cookieHeader(jar: Jar) { return [...jar].map(([n,v]) => `${n}=${v}`).join("; "); }

async function login(email: string, password: string): Promise<Jar> {
