```ts
type Jar = Map<string, string>;
function applySetCookies(jar: Jar, res: Response) {
  for (const sc of res.headers.getSetCookie?.() ?? []) {
    const [pair] = sc.split(";");
    const eq = pair.indexOf("=");
    if (eq < 0) continue;
    const name = pair.slice(0, eq).trim();
    let value = pair.slice(eq + 1).trim();
    if (/^(deleted|undefined)$/i.test(value)) value = "";
    if (value === "") jar.delete(name); else jar.set(name, value);
  }
}
function cookieHeader(jar: Jar) { return [...jar].map(([n,v]) => `${n}=${v}`).join("; "); }

async function login(email: string, password: string): Promise<Jar> {
  const jar: Jar = new Map();
  const csrfRes = await fetch(`${base}/api/auth/csrf`, { headers: { cookie: "" } });
  applySetCookies(jar, csrfRes);
  const { csrfToken } = await csrfRes.json() as { csrfToken: string };
  assert.ok(csrfToken, "CSRF token missing");
  const res = await fetch(`${base}/api/auth/callback/credentials`, {
    method: "POST",
    redirect: "manual",
    headers: {
      "content-type": "application/x-www-form-urlencoded",
      accept: "application/json",
      cookie: cookieHeader(jar),
    },
    body: new URLSearchParams({ csrfToken, email, password }).toString(),
  });
  applySetCookies(jar, res);
  const hasSession = [...jar.keys()].some(n => n.includes("session-token"));
  assert.ok(hasSession, `Login failed for ${email}: ${res.status}`);  // no secrets printed
  return jar;
}
```

