type Dict = Record<string, unknown>;

type ApiJson = {
  success?: unknown;
  message?: unknown;
  data?: unknown;
};

type ApiResponse = { status: number; body: ApiJson };

type Jar = Map<string, string>;

type Account = {
  email: string;
  password: string;
  jar: Jar;
};

// ---------------------------------------------------------------------------
