+// Temporary read-only helper for UI batch verification (gitignored .next/ dir).
+const fs = require("fs");
+const path = require("path");
+
+const env = fs.readFileSync(path.join(__dirname, "..", ".env"), "utf8");
+const match = env.match(/^DATABASE_URL\s*=\s*"?([^"\n]+)"?/m);
+if (!match) {
+  console.log("NO_DATABASE_URL");
+  process.exit(1);
+}
+
+const { Client } = require("pg");
+const client = new Client({
+  connectionString: match[1],
+  connectionTimeoutMillis: 5000,
+  query_timeout: 8000,
+});
+
+const done = (line) => {
+  console.log(line);
+  client.end().catch(() => {});
+  process.exit(0);
+};
+
+client
+  .connect()
+  .then(async () => {
+    const total = await client.query('SELECT count(*) AS n FROM "User"');
+    const admin = await client.query(
+      "SELECT email, role FROM \"User\" WHERE email = 'admin@medorch.local'",
+    );
+    done(
+      `users_total=${total.rows[0].n} admin=${JSON.stringify(admin.rows)}`,
+    );
+  })
+  .catch((e) => done(`PG_ERR: ${String(e.message).split("\n")[0]}`));
+
+setTimeout(() => done("PG_TIMEOUT"), 12000);
